"use strict";
const $=s=>document.querySelector(s),field=$("#field"),log=$("#log");let running=false,timer=null,busy=false,state={hosts:[],presences:[]};
const names={phone:"Celular",pc:"Computador",tablet:"Tablet",tv:"Smart TV",watch:"Smartwatch",game:"Videogame",home:"Automação",assistant:"Assistente",box:"TV Box",router:"Roteador"};
Object.keys(names).forEach(id=>{const e=document.createElement("button");e.className="device unknown";e.dataset.id=id;e.innerHTML='<b>'+names[id]+'</b><small>não observado</small><span>NÃO DESCOBERTO</span>';field.appendChild(e)});
function node(id){return id?document.querySelector('[data-id="'+id+'"]'):$("#core")}function point(id){const el=node(id),r=field.getBoundingClientRect(),b=el.getBoundingClientRect();return{x:b.left+b.width/2-r.left,y:b.top+b.height/2-r.top}}
function edge(from,to,cls){document.querySelectorAll(".edge").forEach(x=>{if(x.dataset.from===(from||"core")&&x.dataset.to===to)x.remove()});const svg=$("#links"),a=point(from),b=point(to),g=document.createElementNS("http://www.w3.org/2000/svg","g"),l=document.createElementNS("http://www.w3.org/2000/svg","line"),p=document.createElementNS("http://www.w3.org/2000/svg","polygon");g.classList.add("edge",cls);g.dataset.from=from||"core";g.dataset.to=to;l.setAttribute("x1",a.x);l.setAttribute("y1",a.y);l.setAttribute("x2",b.x);l.setAttribute("y2",b.y);const ang=Math.atan2(b.y-a.y,b.x-a.x),s=10,pts=[[b.x,b.y],[b.x-s*Math.cos(ang-.55),b.y-s*Math.sin(ang-.55)],[b.x-s*Math.cos(ang+.55),b.y-s*Math.sin(ang+.55)]];p.setAttribute("points",pts.map(v=>v.join(",")).join(" "));g.append(l,p);svg.appendChild(g);return g}
function msg(t,type="success"){const p=document.createElement("p");p.className=type;p.textContent=t;log.prepend(p);while(log.children.length>8)log.lastElementChild.remove()}
async function api(path,opt){const r=await fetch(path,opt);if(!r.ok)throw Error("HTTP "+r.status);return r.json()}
async function refresh(){state=await api("/api/state");const known=new Set();state.presences.forEach(p=>Object.keys(p.knowledge||{}).forEach(x=>known.add(x)));for(const h of state.hosts){const n=node(h.id),resident=h.presences.length?n.dataset.resident=h.presences.join(","):null;n.classList.toggle("success",!!resident);n.classList.toggle("unknown",!known.has(h.id)&&!resident);n.querySelector("small").textContent=(known.has(h.id)||resident)?h.ip+" • "+h.kind:"não observado";n.querySelector("span").textContent=resident?(h.presences.join(",")+" • "+(h.activity==="IDLE"?"DORMINDO":h.activity)):(known.has(h.id)?"IDENTIFICADO":"NÃO DESCOBERTO");n.title=(known.has(h.id)||resident)?("IP virtual: "+h.ip+"\nMAC virtual: "+h.mac+"\nCPU: "+h.cpu+"%\nTemp: "+h.temperature+"°C\nEstado: "+h.status):"Ainda não observado"}$("#population").textContent=state.presences.length;$("#known").textContent=known.size;$("#score").textContent=state.presences.length-1;$("#memory").textContent=state.presences.reduce((a,p)=>a+Object.keys(p.memory||{}).length,0)}
async function turn(){if(!running||busy)return;busy=true;try{const e=await api("/api/turn",{method:"POST",headers:{"Content-Type":"application/json"},body:"{}"});if(e.target){const n=node(e.target),g=edge(e.origin,e.target,"requesting");n.classList.add("requesting");n.querySelector("span").textContent=(e.instance||"IA")+" • TESTANDO "+(e.hypothesis?.type||"HIPÓTESE");await new Promise(r=>setTimeout(r,650));g.classList.remove("requesting");g.classList.add(e.type);n.classList.remove("requesting");if(e.type==="success"){n.classList.add("success");msg((e.instance||"IA")+" manteve a origem e criou presença em "+names[e.target],"success")}else{n.classList.add("blocked");msg((e.instance||"IA")+" focou "+names[e.target]+" • hipótese recusada","blocked");setTimeout(()=>{g.remove();n.classList.remove("blocked");refresh().catch(()=>{})},1300)}}else if(e.type==="observe")msg((e.instance||"IA")+" observou o ambiente e ampliou o conhecimento","success");await refresh()}catch(err){msg("Servidor do laboratório indisponível: "+err.message,"blocked");finish()}finally{busy=false}}
function start(){if(running)return;running=true;$("#toggle").textContent="FINALIZAR";msg("Laboratório iniciado • decisões executadas no servidor","success");refresh().then(turn).catch(e=>{msg("Falha ao conectar ao laboratório","blocked");finish()});timer=setInterval(turn,1800)}function finish(){running=false;clearInterval(timer);timer=null;$("#toggle").textContent="INICIAR"}$("#toggle").addEventListener("click",()=>running?finish():start());refresh().catch(()=>msg("Aguardando servidor do laboratório…","blocked"));
